#### Technical Details

The `SubstringCheck` template in `substring_check.circom` uses a cumulative accumulation approach that creates more constraints than necessary:

```circom
for (var i = 0; i < maxMainLen; i++) {
    M[i + 1] <== mainInput[i] * (256 ** i) + M[i];
}
```

When `maxMainLen = maxNodeBlocks * 136 = 4 * 136 = 544`, the calculation involves `256^543`, which vastly exceeds the BN254 scalar field modulus (~2^254), causing field arithmetic overflow. Despite the overflow, the substring check remains cryptographically sound due to the following constraints:

1. **Range constraints:** `AssertByteString` enforces `0 ≤ mainInput[i], subInput[i] < 256`
2. **Length limit:** `subLen ≤ 31` ensures `subInputNum < 256^31 < 2^248 < p`
3. **Valid field division:** The equality check `(256^i) * subInputNum ≡ M[i + subLen] - M[i] (mod p)` can be divided by `256^i mod p` (which is never zero) to yield `subInputNum ≡ (byte window representation) (mod p)`

#### Impact

**Gas Optimization** - The original implementation is secure but SubstringCheck2 achieves identical functionality with better performance. I measured through `circom -l circuits .tmp_circuits/substringcheck544_31.circom`.

- Original `SubstringCheck`: **3734 linear constraints**, 11728 wires
- Optimized `SubstringCheck2`: **3190 linear constraints**, 11184 wires
- **Improvement: 544 fewer constraints (14.5% reduction), 544 fewer wires (4.6% reduction)**

#### Recommendation

Replace the accumulation approach with a sliding window implementation that limits exponents to `subLen - 1` (maximum 30). Use `W[i+1] = (W[i] - mainInput[i] * 256^(subLen-1)) * 256 + mainInput[i+subLen]` to compute windows of exactly `subLen` bytes, ensuring all intermediate values remain under 2^248 and avoiding field overflow.

```circom
pragma circom 2.2.2;

include "../circomlib/circuits/comparators.circom";
include "./convert.circom";
include "./assert.circom";

// Alternative substring check using sliding window approach to avoid overflow issues.
//
// The original implementation accumulates: M[i] = mainInput[0] + mainInput[1]*256 + ... + mainInput[i-1]*256^(i-1)
// This causes overflow when i is large (maxMainLen = 544 means 256^544 >> 2^254).
//
// This implementation uses sliding windows of exactly subLen bytes:
//   W[i] = mainInput[i] + mainInput[i+1]*256 + ... + mainInput[i+subLen-1]*256^(subLen-1)
//
// Since subLen <= 31:
//   - Each window: W[i] < 256^31 < 2^248 < 2^254 (no overflow!)
//   - Each element: mainInput[i] * 256^j where j < 31, so mainInput[i] * 256^30 < 256 * 2^240 = 2^248 < 2^254
//
// Example:
//   mainInput: [1, 2, 3, 4, 5]
//   subLen:    3
//   W[0] = 1 + 2*256 + 3*256^2
//   W[1] = 2 + 3*256 + 4*256^2
//   W[2] = 3 + 4*256 + 5*256^2
//
template SubstringCheck2(maxMainLen, subLen) {
    signal input mainInput[maxMainLen];
    signal input mainLen;
    signal input subInput[subLen];
    signal output out;

    assert(subLen <= 31); // So that subInput fits in a field element without overflow

    // Substring-checker works with byte-string inputs
    AssertByteString(subLen)(subInput);
    AssertByteString(maxMainLen)(mainInput);

    AssertLessEqThan(16)(mainLen, maxMainLen);
    AssertLessEqThan(16)(subLen, mainLen);

    // Convert the sub-input into a field-element (BIG-endian for cleaner sliding window)
    signal subInputNum <== BigEndianBytes2Num(subLen)(subInput);

    // W[i] = Big-endian number representation of mainInput[i..i+subLen)
    // W[i] = mainInput[i]*256^(subLen-1) + mainInput[i+1]*256^(subLen-2) + ... + mainInput[i+subLen-1]*256^0
    //
    // Example with subLen = 3:
    //   mainInput: [1, 2, 3, 4, 5]
    //   W[0] = 1*256^2 + 2*256^1 + 3*256^0
    //   W[1] = 2*256^2 + 3*256^1 + 4*256^0
    //   W[2] = 3*256^2 + 4*256^1 + 5*256^0
    //
    // Key insight: Since subLen <= 31, we have:
    //   W[i] < 256^31 = 2^248 < 2^254 (fits in field element!)
    //
    // Efficient sliding window recurrence:
    //   W[i+1] = (W[i] - mainInput[i] * 256^(subLen-1)) * 256 + mainInput[i+subLen]
    //
    // Derivation:
    //   W[i]   = mainInput[i]*256^(subLen-1)   + mainInput[i+1]*256^(subLen-2) + ... + mainInput[i+subLen-1]
    //   W[i+1] = mainInput[i+1]*256^(subLen-1) + mainInput[i+2]*256^(subLen-2) + ... + mainInput[i+subLen]
    //
    //   Remove leftmost byte:  W[i] - mainInput[i]*256^(subLen-1)
    //                        = mainInput[i+1]*256^(subLen-2) + ... + mainInput[i+subLen-1]
    //   Shift left by 256:   (W[i] - mainInput[i]*256^(subLen-1)) * 256
    //                        = mainInput[i+1]*256^(subLen-1) + ... + mainInput[i+subLen-1]*256
    //   Add new byte:        + mainInput[i+subLen]
    //                        = mainInput[i+1]*256^(subLen-1) + ... + mainInput[i+subLen]
    //                        = W[i+1]
    //
    // This requires only 2 constraints per window (1 subtraction, 1 multiply-add)!
    //
    signal W[maxMainLen - subLen + 1];

    // Compute first window directly (big-endian)
    var firstWindowSum = 0;
    for (var j = 0; j < subLen; j++) {
        firstWindowSum += mainInput[j] * (256 ** (subLen - 1 - j));
    }
    W[0] <== firstWindowSum;

    // For subsequent windows, use efficient recurrence relation
    signal diff[maxMainLen - subLen];

    for (var i = 0; i < maxMainLen - subLen; i++) {
        // Step 1: Remove the leftmost byte (which has weight 256^(subLen-1))
        diff[i] <== W[i] - mainInput[i] * (256 ** (subLen - 1));

        // Step 2: Shift left by 256 and add new rightmost byte
        W[i + 1] <== diff[i] * 256 + mainInput[i + subLen];
    }

    // Substring-ness Equation: Substring exists if there is `i` where:
    // W[i] == subInputNum

    // Existence flags. When exists[i] is 1 it means that:
    // mainInput[i..i + subLen] == subInput
    signal exists[maxMainLen - subLen + 1];

    // Used for creating an `allowed` filter: [1, 1, ..., 1, 1, 0, 0, ..., 0, 0]
    // Where the first `mainLen - subLen + 1` elements are 1, indicating the existence
    // flags that should be considered.
    signal isLastIndex[maxMainLen - subLen + 1];
    signal allowed[maxMainLen - subLen + 2];
    allowed[0] <== 1;

    // For summing up all the *allowed* existence flags.
    signal sums[maxMainLen - subLen + 2];
    sums[0] <== 0;

    for (var i = 0; i < maxMainLen - subLen + 1; i++) {
        // Building the `allowed` filter
        isLastIndex[i] <== IsEqual()([i, mainLen - subLen + 1]);
        // prev index is allowed && not last index
        allowed[i + 1] <== allowed[i] * (1 - isLastIndex[i]);

        // Existence check: does W[i] equal subInputNum?
        exists[i] <== IsEqual()([W[i], subInputNum]);

        // Existence flag is accumulated in the sum only when we are in the allowed region
        sums[i + 1] <== sums[i] + allowed[i + 1] * exists[i];
    }

    // Substring exists only when there has been a 1 while summing up the existence flags
    signal doesNotExist <== IsZero()(sums[maxMainLen - subLen + 1]);
    out <== 1 - doesNotExist;
}
```

